'use strict';
// The synthetic railway behind the mock service: curvy track between real station coordinates, cut
// into berths ("spans"), and a train timeline over those berths with the noise a real feed has.
// Deterministic for a given seed, so a recorded fixture can be regenerated byte for byte.
//
//   legPath(a, b)        the polyline between two neighbouring stations (same both ways round)
//   routeBerths(route)   the berths of one run of a route, in order, each with its span
//   genRun(train, ...)   one end-to-end run of a train: true times, nominal times, delivery times
//   network(level)       the line layer served at /network?level=lo|hi
//
// Realism that matters to the page, each a parameter of makeNoise():
//   - transit time varies +-25% around the nominal (the service's "learned median"),
//   - 2.5% of berths have a hold at a signal (20-100 s),
//   - a step reaches the client 1-6 s after it happened.
const geo = require('../geo.js');

const KY = 110540;
const kxAt = (lat) => 111320 * Math.cos(lat * Math.PI / 180);

function hash32(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
function mulberry(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ---- polylines ------------------------------------------------------------------------------------
function plen(p) {
  let L = 0;
  for (let i = 1; i < p.length; i++) {
    const kx = kxAt(p[i][0]);
    L += Math.hypot((p[i][1] - p[i - 1][1]) * kx, (p[i][0] - p[i - 1][0]) * KY);
  }
  return L;
}
// The points of p between distances d0 and d1 (metres).
function pslice(p, d0, d1) {
  const out = [];
  let acc = 0;
  const lerp = (a, b, f) => [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f];
  for (let i = 1; i < p.length; i++) {
    const kx = kxAt(p[i][0]);
    const seg = Math.hypot((p[i][1] - p[i - 1][1]) * kx, (p[i][0] - p[i - 1][0]) * KY);
    const s0 = acc, s1 = acc + seg;
    if (s1 >= d0 && s0 <= d1 && seg > 0) {
      const a = Math.max(d0, s0), b = Math.min(d1, s1);
      if (!out.length) out.push(lerp(p[i - 1], p[i], (a - s0) / seg));
      if (b < s1) { out.push(lerp(p[i - 1], p[i], (b - s0) / seg)); }
      else out.push(p[i]);
    }
    acc = s1;
  }
  if (!out.length) out.push(p[0]);
  return out;
}
// Douglas-Peucker, tolerance in metres.
function simplify(p, tolM) {
  if (p.length < 3) return p.slice();
  const keep = new Uint8Array(p.length); keep[0] = keep[p.length - 1] = 1;
  const stack = [[0, p.length - 1]];
  while (stack.length) {
    const [a, b] = stack.pop();
    const kx = kxAt(p[a][0]);
    const ax = p[a][1] * kx, ay = p[a][0] * KY, bx = p[b][1] * kx, by = p[b][0] * KY;
    const dx = bx - ax, dy = by - ay, l2 = dx * dx + dy * dy;
    let md = 0, mi = -1;
    for (let i = a + 1; i < b; i++) {
      const px = p[i][1] * kx - ax, py = p[i][0] * KY - ay;
      const t = l2 ? Math.max(0, Math.min(1, (px * dx + py * dy) / l2)) : 0;
      const d = Math.hypot(px - t * dx, py - t * dy);
      if (d > md) { md = d; mi = i; }
    }
    if (md > tolM && mi > 0) { keep[mi] = 1; stack.push([a, mi], [mi, b]); }
  }
  return p.filter((_, i) => keep[i]);
}
const r5 = (p) => p.map((q) => [Math.round(q[0] * 1e5) / 1e5, Math.round(q[1] * 1e5) / 1e5]);

// ---- the world ------------------------------------------------------------------------------------
function createWorld(stationsByCrs) {
  const LEGS = new Map();          // 'A>B' (canonical order) -> {a, b, path, usage}
  const SPANS = new Map();         // span id -> {id, length, path, stop}
  const RUNS = new Map();          // route key|dir -> berth list

  // The polyline from station a to b, canonical a<b, curvy: two overlaid sinusoids, tapered to
  // zero at both stations so the line meets them exactly.
  function legPath(a, b, usage) {
    const flip = a > b, ca = flip ? b : a, cb = flip ? a : b, key = ca + '>' + cb;
    let leg = LEGS.get(key);
    if (!leg) {
      const A = stationsByCrs[ca], B = stationsByCrs[cb];
      const kx = kxAt((A.lat + B.lat) / 2), dx = (B.lon - A.lon) * kx, dy = (B.lat - A.lat) * KY, len = Math.hypot(dx, dy);
      const rnd = mulberry(hash32(key));
      const n = Math.max(10, Math.min(90, Math.round(len / 140)));
      const amp = Math.min(700, len * (0.035 + rnd() * 0.05)), ph = rnd() * 6.28, f2 = 1.5 + rnd() * 2;
      const nx = -dy / len, ny = dx / len;                      // unit normal, metres
      const path = [];
      for (let i = 0; i <= n; i++) {
        const u = i / n, taper = Math.sin(Math.PI * u);
        const off = amp * taper * (0.65 * Math.sin(Math.PI * u * 2 + ph) + 0.35 * Math.sin(Math.PI * u * f2 * 2 + ph * 2));
        path.push([A.lat + (dy * u + ny * off) / KY, A.lon + (dx * u + nx * off) / kx]);
      }
      path[0] = [A.lat, A.lon]; path[n] = [B.lat, B.lon];
      leg = { a: ca, b: cb, path: r5(path), usage: usage || 'main', length: 0 };
      leg.length = plen(leg.path);
      LEGS.set(key, leg);
    } else if (usage === 'main') leg.usage = 'main';
    return flip ? leg.path.slice().reverse() : leg.path;
  }

  // The berths of one run: legs between consecutive stations, each cut into berths of 350-900 m.
  // calls: Set of CRS where the train stops (the first and last always do).
  function routeBerths(all, calls, dir, usage) {
    const seq = dir ? all.slice().reverse() : all;
    const key = seq.join('-') + '|' + Array.from(calls).sort().join(',');
    let list = RUNS.get(key);
    if (list) return list;
    list = [];
    for (let i = 0; i + 1 < seq.length; i++) {
      const path = legPath(seq[i], seq[i + 1], usage), L = plen(path);
      const nb = Math.max(1, Math.min(10, Math.round(L / 620)));
      const rnd = mulberry(hash32(seq[i] + '>' + seq[i + 1]));
      const w = []; let sum = 0;
      for (let k = 0; k < nb; k++) { const x = rnd() < 0.07 ? 0.1 : 0.75 + rnd() * 0.5; w.push(x); sum += x; }   // now and then a very short berth (a junction throat): a fast train is through it in seconds
      let d = 0;
      for (let k = 0; k < nb; k++) {
        const d1 = k === nb - 1 ? L : d + L * w[k] / sum;
        const sl = pslice(path, d, d1), len = plen(sl);
        const id = 'sp_' + hash32(seq[i] + '>' + seq[i + 1] + '#' + k).toString(16).padStart(8, '0');
        const arrival = k === nb - 1, depart = k === 0;
        const def = {
          id, path: r5(sl), length: Math.round(len * 10) / 10, from: seq[i], to: seq[i + 1], k, nb,
          arrival, depart,
          callsAtEnd: arrival && (calls.has(seq[i + 1]) || i + 2 === seq.length),
          callsAtStart: depart && (calls.has(seq[i]) || i === 0),
          terminus: arrival && i + 2 === seq.length
        };
        // what the span endpoint says about stopping (a property of the berth, whoever uses it)
        const spanStop = arrival ? def.length : depart ? 0 : null;
        SPANS.set(id, { id, length: def.length, path: def.path, stop: spanStop });
        list.push(def);
        d = d1;
      }
    }
    RUNS.set(key, list);
    return list;
  }

  const levelCache = {};
  // The line layer: every leg ever used, simplified (lo is coarser), as GeoJSON.
  function network(level) {
    const ck = level + ':' + LEGS.size;
    if (levelCache[ck]) return levelCache[ck];
    const tol = level === 'lo' ? 80 : 4;
    const features = [];
    LEGS.forEach((leg) => {
      const s = simplify(leg.path, tol);
      features.push({ type: 'Feature', properties: { u: leg.usage }, geometry: { type: 'LineString', coordinates: r5(s).map((q) => [q[1], q[0]]) } });
    });
    return (levelCache[ck] = { type: 'FeatureCollection', features });
  }

  return { legPath, routeBerths, network, LEGS, SPANS };
}

// ---- the train timeline ---------------------------------------------------------------------------
// Design speeds (m/s) per class and how long a stop lasts, nominally.
const SPEED = { express: 33, stopping: 24, ecs: 20, freight: 16, special: 20 };
const DWELL = { express: 40, stopping: 40, ecs: 30, freight: 0, special: 0 };
const LAYOVER = 150;

// The nominal ("learned median") seconds in a berth.
function nominal(def, cls, calls) {
  const v = SPEED[cls] || 22, L = def.length, a = 0.7;
  if (def.callsAtEnd) {
    const approach = L / (v * 0.78);
    return approach + (def.terminus ? LAYOVER : DWELL[cls] || 30);
  }
  if (def.callsAtStart) return L > v * v / (2 * a) ? L / v + v / (2 * a) : Math.sqrt(2 * L / a);
  return Math.max(4, L / v);
}

// noise: { transit: 0.25, holdP: 0.025, holdMin: 20, holdMax: 100, delayMin: 1, delayMax: 6, mode: 'iid' | 'persistent' }
function makeNoise(o) {
  return Object.assign({ transit: 0.25, holdP: 0.025, holdMin: 20, holdMax: 100, delayMin: 1, delayMax: 6, mode: 'iid' }, o || {});
}

// One run of a train. Times in ms. Returns { dir, start, nomStart, berths: [{def, t0, T, Tn, D, hold, deliverAt}], end }
function genRun(world, train, dir, startMs, rnd, noise) {
  const defs = world.routeBerths(train.route.all, train.calls, dir, train.route.usage);
  const berths = [];
  const nomStart = startMs - Math.round(rnd() * 40000);
  let t = startMs, nomT = nomStart;
  let lastDeliver = 0;
  const pace = train.pace;
  for (let i = 0; i < defs.length; i++) {
    const def = defs[i], Mn = nominal(def, train.cls, train.calls);
    let f;
    if (noise.mode === 'persistent') f = pace * (1 + (rnd() * 2 - 1) * noise.transit * 0.45);
    else f = 1 + (rnd() * 2 - 1) * noise.transit;
    f = Math.max(1 - noise.transit, Math.min(1 + noise.transit, f));
    let T = Mn * f, hold = 0;
    if (!def.callsAtEnd && !def.callsAtStart && rnd() < noise.holdP) hold = noise.holdMin + rnd() * (noise.holdMax - noise.holdMin);
    const dwellNom = def.callsAtEnd ? (def.terminus ? LAYOVER : DWELL[train.cls] || 30) : 0;
    const e = { def, delay: 0, t0: t, T: (T + hold) * 1000, Tm: T * 1000, Tn: Mn * 1000, D: dwellNom * f, dNom: dwellNom, hold: hold * 1000, nom0: nomT };
    const d = noise.delayMin + rnd() * (noise.delayMax - noise.delayMin);
    e.delay = d * 1000;
    e.deliverAt = Math.max(t + d * 1000, lastDeliver);
    lastDeliver = e.deliverAt;
    berths.push(e);
    t += e.T; nomT += e.Tn;
  }
  return { dir, start: startMs, nomStart: nomStart, end: t, berths, defs };
}

module.exports = { createWorld, genRun, makeNoise, nominal, plen, simplify, pslice, mulberry, hash32, SPEED, DWELL, LAYOVER, kxAt, KY };
void geo;
